        cycle = [None] * period
        valid = True
        for r in range(1, height):
            for c, value in enumerate(grid[r]):
                if value == 0 or c == r:
                    continue
                slot = c % period
                if cycle[slot] is None:
                    cycle[slot] = value
                elif cycle[slot] != value:
                    valid = False
                    break
            if not valid:
                break
        if valid and all(value is not None for value in cycle):
            return cycle
    raise ValueError('Could not infer the repeated color sequence')


def transform(grid):
    """Restore erased cells in the periodic field with its shifted diagonal.

    Rows below the top edge follow the inferred cycle by column, except that
    the diagonal repeats the preceding cycle color. The top row is phase-shifted
    one cell earlier and has a unique preserved corner at (0, 0).
    """
    cycle = _infer_cycle(grid)
    period = len(cycle)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                continue
            if r == 0:
                if c > 0:
                    out[r][c] = cycle[(c - 1) % period]
            elif c == r:
                out[r][c] = cycle[(c - 1) % period]
            else:
                out[r][c] = cycle[c % period]
    return out


